ALTER TABLE public.projects ADD COLUMN client_id uuid, ADD COLUMN client_name text NOT NULL DEFAULT '', ADD COLUMN client_email text, ADD COLUMN client_phone text, ADD COLUMN address text, ADD COLUMN city text, ADD COLUMN neighborhood text, ADD COLUMN property_type text, ADD COLUMN area_sqm integer, ADD COLUMN end_date date, ADD COLUMN current_phase integer DEFAULT 1, ADD COLUMN total_phases integer DEFAULT 5, ADD COLUMN progress_percent integer DEFAULT 0, ADD COLUMN total_price numeric(10,2), ADD COLUMN paid_amount numeric(10,2) DEFAULT 0, ADD COLUMN currency text DEFAULT 'EUR', ADD COLUMN source_request_id uuid REFERENCES public.renovation_requests(id) ON DELETE SET NULL, ADD COLUMN project_manager_id uuid, ADD COLUMN hero_image_url text, ADD COLUMN is_draft boolean NOT NULL DEFAULT false;
UPDATE public.projects SET client_id=user_id, client_name=COALESCE((SELECT COALESCE(full_name,email) FROM public.profiles WHERE id=user_id),'Klijent'), address=location, property_type=type, progress_percent=progress;
ALTER TABLE public.projects DROP CONSTRAINT projects_status_check;
UPDATE public.projects SET status=CASE status WHEN 'planned' THEN 'procjena' WHEN 'active' THEN 'izvodenje' WHEN 'completed' THEN 'zavrseno' ELSE status END;
ALTER TABLE public.projects ALTER COLUMN status SET DEFAULT 'procjena', ALTER COLUMN user_id SET DEFAULT auth.uid(), ADD CONSTRAINT projects_status_check CHECK (status IN ('procjena','ugovor','priprema','izvodenje','predaja','zavrseno','odbijeno')), ADD CONSTRAINT projects_progress_percent_check CHECK(progress_percent BETWEEN 0 AND 100);
COMMENT ON COLUMN public.projects.user_id IS 'DEPRECATED: legacy creator/owner compatibility; client access uses client_id.';
COMMENT ON COLUMN public.projects.progress IS 'DEPRECATED: replaced by progress_percent';
COMMENT ON COLUMN public.projects.type IS 'DEPRECATED: replaced by property_type';
COMMENT ON COLUMN public.projects.location IS 'DEPRECATED: replaced by address, city and neighborhood';
CREATE INDEX idx_projects_client ON public.projects(client_id);
CREATE INDEX idx_projects_status ON public.projects(status);
CREATE UNIQUE INDEX idx_projects_source_request ON public.projects(source_request_id) WHERE source_request_id IS NOT NULL;
ALTER TABLE public.renovation_requests ADD COLUMN property_address text, ADD COLUMN client_id uuid, ADD COLUMN city text;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.projects TO authenticated;
GRANT ALL ON public.projects TO service_role;
DROP POLICY IF EXISTS "Admins can insert projects for users" ON public.projects;
DROP POLICY IF EXISTS "Admins can update all projects" ON public.projects;
DROP POLICY IF EXISTS "Admins can view all projects" ON public.projects;
DROP POLICY IF EXISTS "Users can insert own projects" ON public.projects;
DROP POLICY IF EXISTS "Users can update own projects" ON public.projects;
DROP POLICY IF EXISTS "Users can view own projects" ON public.projects;
CREATE POLICY "Staff can view all projects" ON public.projects FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
CREATE POLICY "Staff can insert projects" ON public.projects FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
CREATE POLICY "Staff can update projects" ON public.projects FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
CREATE POLICY "Clients can view own projects" ON public.projects FOR SELECT TO authenticated USING(client_id=auth.uid() AND NOT is_draft);
CREATE TABLE public.project_phases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,name text NOT NULL,phase_order integer NOT NULL,status text NOT NULL DEFAULT 'planirano' CHECK(status IN ('planirano','u_tijeku','zavrseno')),start_date date,end_date date,completed_at timestamptz,notes text,created_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.project_phases TO authenticated;
GRANT ALL ON public.project_phases TO service_role;
ALTER TABLE public.project_phases ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff can manage all phases" ON public.project_phases FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
CREATE POLICY "Clients can view phases of own projects" ON public.project_phases FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.client_id=auth.uid() AND NOT p.is_draft));
CREATE UNIQUE INDEX idx_phases_order ON public.project_phases(project_id,phase_order);
CREATE TABLE public.project_internal_notes(project_id uuid PRIMARY KEY REFERENCES public.projects(id) ON DELETE CASCADE,internal_notes text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.project_internal_notes TO authenticated;
GRANT ALL ON public.project_internal_notes TO service_role;
ALTER TABLE public.project_internal_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff only internal notes" ON public.project_internal_notes FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER projects_set_updated_at BEFORE UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.project_managers() RETURNS TABLE(id uuid,full_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,COALESCE(p.full_name,p.email,'Voditelj') FROM public.profiles p WHERE (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.id AND r.role IN ('admin','moderator')); $$;
REVOKE ALL ON FUNCTION public.project_managers() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.project_managers() TO authenticated;
CREATE OR REPLACE FUNCTION public.create_project_from_request(request_id uuid,details jsonb,phases jsonb,save_draft boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r public.renovation_requests; pid uuid; linked_client uuid; existing_draft boolean; manager uuid; s text; phase jsonb; idx integer:=0;
BEGIN
IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) THEN RAISE EXCEPTION 'Staff access required' USING ERRCODE='42501'; END IF;
SELECT * INTO r FROM public.renovation_requests WHERE id=request_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
SELECT id,is_draft INTO pid,existing_draft FROM public.projects WHERE source_request_id=request_id;
IF pid IS NOT NULL AND NOT existing_draft THEN RAISE EXCEPTION 'Request already converted'; END IF;
IF COALESCE(trim(details->>'title'),'')='' THEN RAISE EXCEPTION 'Title required'; END IF;
s:=details->>'status'; IF s NOT IN ('procjena','ugovor','priprema') OR s IS NULL THEN RAISE EXCEPTION 'Invalid initial status'; END IF;
manager:=(details->>'project_manager_id')::uuid;
IF manager IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=manager AND role IN ('admin','moderator')) THEN RAISE EXCEPTION 'Valid manager required'; END IF;
IF jsonb_typeof(phases) IS DISTINCT FROM 'array' OR jsonb_array_length(phases)<1 THEN RAISE EXCEPTION 'At least one phase required'; END IF;
IF (details->>'total_price')::numeric<0 THEN RAISE EXCEPTION 'Price must be non-negative'; END IF;
IF (details->>'end_date')::date < (details->>'start_date')::date THEN RAISE EXCEPTION 'Delivery precedes start'; END IF;
SELECT id INTO linked_client FROM public.profiles WHERE lower(email)=lower(r.email) LIMIT 1;
IF pid IS NULL THEN
INSERT INTO public.projects(user_id,title,client_id,client_name,client_email,client_phone,address,city,neighborhood,property_type,area_sqm,status,start_date,end_date,project_manager_id,total_price,source_request_id,total_phases,is_draft) VALUES(auth.uid(),trim(details->>'title'),linked_client,r.name,r.email,r.phone,r.property_address,r.city,r.location,r.property_type,r.sqm,s,(details->>'start_date')::date,(details->>'end_date')::date,manager,(details->>'total_price')::numeric,r.id,jsonb_array_length(phases),save_draft) RETURNING id INTO pid;
ELSE
UPDATE public.projects SET title=trim(details->>'title'),status=s,start_date=(details->>'start_date')::date,end_date=(details->>'end_date')::date,project_manager_id=manager,total_price=(details->>'total_price')::numeric,total_phases=jsonb_array_length(phases),is_draft=save_draft,client_id=linked_client WHERE id=pid;
DELETE FROM public.project_phases WHERE project_id=pid;
END IF;
FOR phase IN SELECT value FROM jsonb_array_elements(phases) LOOP
idx:=idx+1;
IF COALESCE(trim(phase->>'name'),'')='' THEN RAISE EXCEPTION 'Phase name required'; END IF;
INSERT INTO public.project_phases(project_id,name,phase_order,end_date,status) VALUES(pid,trim(phase->>'name'),idx,(phase->>'end_date')::date,CASE WHEN idx=1 AND NOT save_draft THEN 'u_tijeku' ELSE 'planirano' END);
END LOOP;
INSERT INTO public.project_internal_notes(project_id,internal_notes) VALUES(pid,details->>'internal_notes') ON CONFLICT(project_id) DO UPDATE SET internal_notes=EXCLUDED.internal_notes;
IF NOT save_draft THEN UPDATE public.renovation_requests SET status='pretvoreno' WHERE id=r.id; END IF;
INSERT INTO public.project_activity_log(project_id,actor_id,action,metadata) VALUES(pid,auth.uid(),CASE WHEN save_draft THEN 'project_draft_saved' ELSE 'project_created' END,jsonb_build_object('from_request',true,'request_id',r.id));
RETURN pid;
END; $$;
REVOKE ALL ON FUNCTION public.create_project_from_request(uuid,jsonb,jsonb,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_project_from_request(uuid,jsonb,jsonb,boolean) TO authenticated;